package sohal.lld.snakeladder.player;public class Player {    private String name;    private int pos;    public Player(String name, int pos) {        this.name = name;        this.pos = pos;    }    public int getPosition() {        return pos;    }    public void setPosition(int position) {        this.pos = position;    }    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }}